    vis = [True] * (n + 1)
    ps = []
    for i in range(2, n + 1):
        if not vis[i]:
            continue
        ps.append(i)
        start = i * i
        if start > n:
            continue
        for j in range(start, n + 1, i):
            vis[j] = False
    return ps

primes = sieve(32000)

def factorize(x):
    fac = []
    for p in primes:
        if p * p > x:
            break
        if x % p == 0:
            fac.append(p)
            while x % p == 0:
                x //= p
    if x > 1:
        fac.append(x)
    return fac

m, t = map(int, input().split())
v = list(map(int, input().split()))  # 传感读数
pid, pc = {}, 0
